// Get the incoming item from the Webhook
const input = $input.first().json;

// Voiceflow normally submits JSON inside "body".
// This also supports directly received or stringified JSON.
let body = input.body ?? input;

if (typeof body === "string") {
  try {
    body = JSON.parse(body);
  } catch {
    throw new Error(
      "The submitted contact-request data could not be read."
    );
  }
}

if (!body || typeof body !== "object") {
  throw new Error(
    "The submitted contact-request data is missing or invalid."
  );
}


// Clean a field and replace missing Voiceflow values
function clean(
  value,
  defaultValue = "Not specified"
) {
  if (
    value === undefined ||
    value === null
  ) {
    return defaultValue;
  }

  const text = String(value).trim();

  if (
    text === "" ||
    text === "0"
  ) {
    return defaultValue;
  }

  return text;
}


// Preserve the phone number exactly as Voiceflow sends it
function preservePhone(
  value,
  defaultValue = "Not specified"
) {
  if (
    value === undefined ||
    value === null
  ) {
    return defaultValue;
  }

  const phone = String(value);

  if (
    phone.trim() === "" ||
    phone.trim() === "0"
  ) {
    return defaultValue;
  }

  return phone;
}


// Validate and lowercase an email when one is provided
function cleanEmail(value) {
  const cleaned = clean(value);

  // Email is optional because a phone number
  // may be provided instead.
  if (cleaned === "Not specified") {
    return "Not specified";
  }

  const email = cleaned.toLowerCase();

  if (email.length > 254) {
    throw new Error(
      "The email address is too long. The contact request was not saved."
    );
  }

  if (/\s/.test(email)) {
    throw new Error(
      "The email address contains spaces. The contact request was not saved."
    );
  }

  const emailParts = email.split("@");

  if (emailParts.length !== 2) {
    throw new Error(
      "The email address must contain exactly one @ symbol. The contact request was not saved."
    );
  }

  const [localPart, domain] = emailParts;

  if (!localPart || !domain) {
    throw new Error(
      "The email address is incomplete. The contact request was not saved."
    );
  }

  if (localPart.length > 64) {
    throw new Error(
      "The email address is invalid. The contact request was not saved."
    );
  }

  if (
    localPart.startsWith(".") ||
    localPart.endsWith(".") ||
    localPart.includes("..") ||
    domain.includes("..")
  ) {
    throw new Error(
      "The email address contains an invalid period placement. The contact request was not saved."
    );
  }

  const validLocalPart =
    /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+$/i;

  if (!validLocalPart.test(localPart)) {
    throw new Error(
      "The email address contains an unsupported character. The contact request was not saved."
    );
  }

  if (!domain.includes(".")) {
    throw new Error(
      "The email domain is incomplete. The contact request was not saved."
    );
  }

  const domainParts = domain.split(".");

  for (const domainPart of domainParts) {
    if (
      !domainPart ||
      domainPart.length > 63 ||
      !/^[a-z0-9-]+$/i.test(domainPart) ||
      domainPart.startsWith("-") ||
      domainPart.endsWith("-")
    ) {
      throw new Error(
        "The email domain is invalid. The contact request was not saved."
      );
    }
  }

  const topLevelDomain =
    domainParts[domainParts.length - 1];

  if (
    !/^[a-z]{2,63}$/i.test(
      topLevelDomain
    )
  ) {
    throw new Error(
      "The email domain ending is invalid. The contact request was not saved."
    );
  }

  return email;
}


// Normalise urgency
function cleanUrgency(value) {
  const urgency = clean(
    value,
    "Normal"
  ).toLowerCase();

  return urgency === "urgent"
    ? "Urgent"
    : "Normal";
}


// Normalise the preferred contact method
function cleanContactMethod(value) {
  const method = clean(value);
  const normalized = method.toLowerCase();

  if (normalized.includes("email")) {
    return "Email";
  }

  if (
    normalized.includes("text") ||
    normalized.includes("sms")
  ) {
    return "Text Message";
  }

  if (
    normalized.includes("phone") ||
    normalized.includes("call")
  ) {
    return "Phone Call";
  }

  return method;
}


// Validate an optional IANA timezone
function cleanTimezone(value) {
  const timezone = clean(value);

  if (timezone === "Not specified") {
    return "Not specified";
  }

  try {
    new Intl.DateTimeFormat(
      "en-US",
      {
        timeZone: timezone
      }
    ).format(new Date());
  } catch {
    throw new Error(
      `The callback timezone "${timezone}" is invalid. The contact request was not saved.`
    );
  }

  return timezone;
}


// Validate an optional ISO 8601 UTC timestamp
function cleanUtcTimestamp(value) {
  const timestamp = clean(value);

  if (timestamp === "Not specified") {
    return "Not specified";
  }

  const parsedTimestamp = Date.parse(
    timestamp
  );

  if (Number.isNaN(parsedTimestamp)) {
    throw new Error(
      "The callback UTC date and time is invalid. The contact request was not saved."
    );
  }

  return new Date(
    parsedTimestamp
  ).toISOString();
}


// Clean contact details before validation
const phone = preservePhone(
  body.phone
);

const email = cleanEmail(
  body.email
);

const preferredContactMethod =
  cleanContactMethod(
    body.preferred_contact_method
  );


// Require at least one usable contact detail
if (
  phone === "Not specified" &&
  email === "Not specified"
) {
  throw new Error(
    "At least one phone number or valid email address is required. The contact request was not saved."
  );
}


// Ensure the preferred method matches the supplied detail
if (
  preferredContactMethod === "Email" &&
  email === "Not specified"
) {
  throw new Error(
    "Email was selected as the preferred contact method, but no valid email address was provided."
  );
}

if (
  (
    preferredContactMethod === "Phone Call" ||
    preferredContactMethod === "Text Message"
  ) &&
  phone === "Not specified"
) {
  throw new Error(
    "A phone number is required for phone-call or text-message contact."
  );
}


// Clean callback timezone and UTC timestamp
const requestedTimeTimezone =
  cleanTimezone(
    body.requested_time_timezone
  );

const requestedDatetimeUtc =
  cleanUtcTimestamp(
    body.requested_datetime_utc
  );


// Generate submission date and timestamp.
// Prefer a supplied business timezone, then the callback timezone, then UTC.
const submissionTimezoneCandidate =
  clean(
    body.business_timezone ??
    body.requested_time_timezone,
    "UTC"
  );

let submissionTimezone = submissionTimezoneCandidate;

try {
  new Intl.DateTimeFormat(
    "en-US",
    { timeZone: submissionTimezone }
  ).format(new Date());
} catch {
  submissionTimezone = "UTC";
}

const now = new Date();

const parts =
  new Intl.DateTimeFormat(
    "en-GB",
    {
      timeZone: submissionTimezone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hour12: false,
      hourCycle: "h23"
    }
  ).formatToParts(now);

const getPart = (type) =>
  parts.find(
    (part) => part.type === type
  )?.value;

const year = getPart("year");
const month = getPart("month");
const day = getPart("day");
const hour = getPart("hour");
const minute = getPart("minute");
const second = getPart("second");

const dateSubmitted =
  `${year}-${month}-${day}`;

const timestamp =
  `${dateSubmitted} ${hour}:${minute}:${second}`;


// Generate a unique contact-request ID
const randomPart = Math.random()
  .toString(36)
  .slice(2, 8)
  .toUpperCase();

const contactRequestId =
  `CONTACT-${year}${month}${day}-${Date.now()}-${randomPart}`;


// Return one flattened item for Google Sheets
return [
  {
    json: {
      contact_request_id:
        contactRequestId,

      name: clean(
        body.name
      ),

      // Preserve exactly as entered
      phone,

      // Lowercase and validate when supplied
      email,

      reason_for_contact: clean(
        body.reason_for_contact
      ),

      message: clean(
        body.message
      ),

      community_or_property: clean(
        body.community_or_property
      ),

      urgency: cleanUrgency(
        body.urgency
      ),

      preferred_contact_method:
        preferredContactMethod,

      best_time_to_contact: clean(
        body.best_time_to_contact
      ),

      requested_time_timezone:
        requestedTimeTimezone,

      requested_datetime_utc:
        requestedDatetimeUtc,

      request_status: "Pending",

      submission_timezone:
        submissionTimezone,

      date_submitted:
        dateSubmitted,

      timestamp
    }
  }
];
